                { id: 3, title: 'Leather Weekend Bag', price: '$180', category: 'Travel', image: 'https://images.unsplash.com/photo-1547949003-9792a18a2601?auto=format&fit=crop&q=80&w=800' },
                { id: 4, title: 'Cotton Work Shirt', price: '$75', category: 'Apparel', image: 'https://images.unsplash.com/photo-1598033129183-c4f50c717658?auto=format&fit=crop&q=80&w=800' },
            ];

            return (
