                    <div className="flex justify-between items-end mb-8">
                        <div>
                            <h2 id="featured-heading" className="text-3xl font-bold tracking-tight text-gray-900">Featured Products</h2>
                            <p className="mt-2 text-gray-600">Handpicked selections for your lifestyle.</p>
                        </div>
                        <a href="#" className="hidden sm:block text-indigo-600 font-semibold hover:text-indigo-500">
                            View All <span aria-hidden="true">&rarr;</span>
                        </a>
                    </div>
                    <ul className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-8">
                        {products.map(product => (
                            <li key={product.id}>
                                <ProductCard {...product} />
                            </li>
                        ))}
                    </ul>
                </section>
            );
        };

        const DealsSection = () => (
            <section className="bg-indigo-50 py-16" aria-labelledby="deals-heading">
                <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
